Single.Single:
// Pass-through call: inputs read from instance variables (set via online API),
// outputs written back to instance variables.
fbArith(rA := fbArith.rA, rB := fbArith.rB,
        eOp := fbArith.eOp, xExecute := fbArith.xExecute);

fbScale(rRaw := fbScale.rRaw, rRawMin := fbScale.rRawMin,
        rRawMax := fbScale.rRawMax, rScaledMin := fbScale.rScaledMin,
        rScaledMax := fbScale.rScaledMax, xExecute := fbScale.xExecute);

fbDeadband(rValue := fbDeadband.rValue, rBand := fbDeadband.rBand,
           xExecute := fbDeadband.xExecute);

fbRangeCheck(rValue := fbRangeCheck.rValue, rMin := fbRangeCheck.rMin,
             rMax := fbRangeCheck.rMax, xExecute := fbRangeCheck.xExecute);

fbChecksum(bA := fbChecksum.bA, bB := fbChecksum.bB,
           bC := fbChecksum.bC, xExecute := fbChecksum.xExecute);

fbCounter(xUp := fbCounter.xUp, xDown := fbCounter.xDown,
          xReset := fbCounter.xReset, uiLimit := fbCounter.uiLimit);

PROGRAM MAIN
VAR
	// CI/CD test instances â variables visible via read_variable/write_variable
	fbArith : FB_Arithmetic;
	fbScale : FB_Scale;
	fbDeadband : FB_Deadband;
	fbRangeCheck : FB_RangeCheck;
	fbChecksum : FB_Checksum;
	fbCounter : FB_Counter_UD;
END_VAR

IF xExecute AND NOT xPrev THEN
	CASE eOp OF
		0: rResult := rA + rB;
		1: rResult := rA - rB;
		2: rResult := rA * rB;
		3: 
			IF rB <> 0.0 THEN
				rResult := rA / rB;
			ELSE
				rResult := 0.0;
			END_IF
		ELSE
			rResult := 0.0;
	END_CASE
	xDone := TRUE;
END_IF

IF NOT xExecute THEN
	xDone := FALSE;
END_IF

xPrev := xExecute;

FUNCTION_BLOCK FB_Arithmetic
VAR_INPUT
	rA : REAL;
	rB : REAL;
	eOp : USINT; // 0=Add, 1=Sub, 2=Mul, 3=Div
	xExecute : BOOL;
END_VAR
VAR_OUTPUT
	rResult : REAL;
	xDone : BOOL;
END_VAR
VAR
	xPrev : BOOL;
END_VAR

IF xExecute AND NOT xPrev THEN
	bResult := bA XOR bB XOR bC;
	xDone := TRUE;
END_IF

IF NOT xExecute THEN
	xDone := FALSE;
END_IF

xPrev := xExecute;

FUNCTION_BLOCK FB_Checksum
VAR_INPUT
	bA : BYTE;
	bB : BYTE;
	bC : BYTE;
	xExecute : BOOL;
END_VAR
VAR_OUTPUT
	bResult : BYTE;
	xDone : BOOL;
END_VAR
VAR
	xPrev : BOOL;
END_VAR

IF xExecute AND NOT xPrev THEN
	IF rValue >= -rBand AND rValue <= rBand THEN
		rResult := 0.0;
	ELSE
		rResult := rValue;
	END_IF
	xDone := TRUE;
END_IF

IF NOT xExecute THEN
	xDone := FALSE;
END_IF

xPrev := xExecute;

FUNCTION_BLOCK FB_Deadband
VAR_INPUT
	rValue : REAL;
	rBand : REAL;
	xExecute : BOOL;
END_VAR
VAR_OUTPUT
	rResult : REAL;
	xDone : BOOL;
END_VAR
VAR
	xPrev : BOOL;
END_VAR

IF xExecute AND NOT xPrev THEN
	xInRange := rValue >= rMin AND rValue <= rMax;
	xDone := TRUE;
END_IF

IF NOT xExecute THEN
	xDone := FALSE;
END_IF

xPrev := xExecute;

FUNCTION_BLOCK FB_RangeCheck
VAR_INPUT
	rValue : REAL;
	rMin : REAL;
	rMax : REAL;
	xExecute : BOOL;
END_VAR
VAR_OUTPUT
	xInRange : BOOL;
	xDone : BOOL;
END_VAR
VAR
	xPrev : BOOL;
END_VAR

IF xExecute AND NOT xPrev THEN
	IF rRawMax <> rRawMin THEN
		rResult := rScaledMin + (rRaw - rRawMin) / (rRawMax - rRawMin) * (rScaledMax - rScaledMin);
	ELSE
		rResult := rScaledMin;
	END_IF
	// Clamp
	IF rResult < rScaledMin THEN rResult := rScaledMin; END_IF
	IF rResult > rScaledMax THEN rResult := rScaledMax; END_IF
	xDone := TRUE;
END_IF

IF NOT xExecute THEN
	xDone := FALSE;
END_IF

xPrev := xExecute;

FUNCTION_BLOCK FB_Scale
VAR_INPUT
	rRaw : REAL;
	rRawMin : REAL;
	rRawMax : REAL;
	rScaledMin : REAL;
	rScaledMax : REAL;
	xExecute : BOOL;
END_VAR
VAR_OUTPUT
	rResult : REAL;
	xDone : BOOL;
END_VAR
VAR
	xPrev : BOOL;
END_VAR

// [INFO] Task with write access: Task (set manually in CODESYS, not restored by import)
{attribute 'qualified_only'}
VAR_GLOBAL
	iInteger : INT; // [INFO] Integer variable
END_VAR

{attribute 'qualified_only'}
{attribute 'strict'}
TYPE _02_DUT_Enumeration :
(
	IDLE := 0,      // System waiting
	STARTING,       // Transition to running
	RUNNING,        // Active operation
	STOPPING,       // Controlled shutdown
	ERROR := 99     // Fault state
) INT;
END_TYPE

{attribute 'qualified_only'}
{attribute 'strict'}
TYPE _02_DUT_Enumeration :
(
	IDLE := 0,      // System waiting
	STARTING,       // Transition to running
	RUNNING,        // Active operation
	STOPPING,       // Controlled shutdown
	ERROR := 99     // Fault state
) INT;
END_TYPE

{attribute 'qualified_only'}
VAR_GLOBAL
    // === Global Commands (HMI -> PLC) ===
    xStart: BOOL; // Master Start pulse for all zones
    xStop: BOOL; // Master Stop pulse for all zones
    xReset: BOOL; // Master Reset for all errors
    xReverse: BOOL; // Global direction control (Logic Level)
    xEmitt1: BOOL;
    xEmitt2: BOOL;


    // === Global Status (PLC -> HMI) ===
    xAnyError: BOOL; // True if any zone in error state
    xAnyWarning: BOOL; // True if any zone has a warning
    xSystemOK: BOOL; // True if communication and all zones are OK
    xRunning: BOOL; // True if at least one conveyor is moving

    // === Visualization Mapping ===
    // This array holds references to the frames used by the HMI.
    // It is initialized in MAIN.st to point to VISUALIZATION.aFrames.
    arConveyors: ARRAY[1..4] OF DUT_CONV_FRAME;

	arErrors : ARRAY[0..10] OF BOOL;

END_VAR

TYPE DUT_CONV_FRAME :
STRUCT
	conv_idx : INT := 1;      // Index in ZONE_MFL.g_aConfigs (1..4)
	sName : STRING(16);       // Safe name copy
	state : STRING(15);       // String representation of state
	//config : DUT_MFL_Config;  // Config copy for visualization
	dimension : INT := 50;    // [mm] segment size for ASCII
	pec_idx : USINT := 1;     // Which PEC to show slip for (1..10)
	iInstantSlip : INT;       // Current/Last measured slip [mm]

	// Compatibility fields for older Visu
	conv_number : INT; 
	pec_choice : INT;
	pecAverageSlip : INT;

	asciiString : STRING(255); // The visual representation
END_STRUCT
END_TYPE

// Reset
IF xReset THEN
	uiValue := 0;
	xLimitReached := FALSE;
	_xUpPrev := FALSE;
	_xDownPrev := FALSE;
	RETURN;
END_IF

// Rising edge up
IF xUp AND NOT _xUpPrev THEN
	IF uiValue < uiLimit THEN
		uiValue := uiValue + 1;
	END_IF
END_IF
_xUpPrev := xUp;

// Rising edge down
IF xDown AND NOT _xDownPrev THEN
	IF uiValue > 0 THEN
		uiValue := uiValue - 1;
	END_IF
END_IF
_xDownPrev := xDown;

// Limit detection
xLimitReached := uiValue >= uiLimit;

FUNCTION_BLOCK FB_Counter_UD
VAR_INPUT
	xUp : BOOL := FALSE;
	xDown : BOOL := FALSE;
	xReset : BOOL := FALSE;
	uiLimit : UINT := 100;
END_VAR
VAR_OUTPUT
	uiValue : UINT := 0;
	xLimitReached : BOOL := FALSE;
END_VAR
VAR
	_xUpPrev : BOOL := FALSE;
	_xDownPrev : BOOL := FALSE;
END_VAR

// Detect rising edge
IF xTrig AND NOT _xTrigPrev THEN
	_timer(IN := TRUE, PT := tDelay);
END_IF
_xTrigPrev := xTrig;

// Run timer
_timer();

xOut := _timer.Q;
xElapsed := _timer.Q AND NOT _xTrigPrev;

FUNCTION_BLOCK FB_Delay
VAR_INPUT
	xTrig : BOOL := FALSE;
	tDelay : TIME := T#1s;
END_VAR
VAR_OUTPUT
	xOut : BOOL := FALSE;
	xElapsed : BOOL := FALSE;
END_VAR
VAR
	_timer : TON;
	_xTrigPrev : BOOL := FALSE;
END_VAR

// Stop
IF xStop THEN
	_running := FALSE;
	_pulseCount := 0;
	xPulse := FALSE;
	xBusy := FALSE;
	xDone := FALSE;
	RETURN;
END_IF

// Start on rising edge
IF xStart AND NOT _xStartPrev THEN
	_running := TRUE;
	_pulseCount := 0;
	xDone := FALSE;
END_IF
_xStartPrev := xStart;

IF _running THEN
	_timer(IN := TRUE, PT := tPeriod);
	xPulse := _timer.Q;

	IF _timer.Q THEN
		_pulseCount := _pulseCount + 1;
		IF _pulseCount >= uiPulseCount THEN
			_running := FALSE;
			xDone := TRUE;
		END_IF
	END_IF

	xBusy := TRUE;
ELSE
	_timer(IN := FALSE);
	xPulse := FALSE;
	xBusy := FALSE;
END_IF

FUNCTION_BLOCK FB_PulseTrain
VAR_INPUT
	xStart : BOOL := FALSE;
	xStop : BOOL := FALSE;
	uiPulseCount : UINT := 10;
	tPeriod : TIME := T#500ms;
END_VAR
VAR_OUTPUT
	xPulse : BOOL := FALSE;
	xBusy : BOOL := FALSE;
	xDone : BOOL := FALSE;
END_VAR
VAR
	_timer : TP;
	_pulseCount : UINT := 0;
	_xStartPrev : BOOL := FALSE;
	_running : BOOL := FALSE;
END_VAR

IF xReset THEN
	_state := 0;
	xRed := FALSE; xYellow := FALSE; xGreen := FALSE;
	eState := 0;
	_timer(IN := FALSE);
	RETURN;
END_IF

// Start on rising edge
IF xRun AND NOT _xRunPrev THEN
	_state := 0;
	_timer(IN := TRUE, PT := _times[0]);
END_IF
_xRunPrev := xRun;

IF NOT xRun THEN
	_timer(IN := FALSE);
	xRed := FALSE; xYellow := FALSE; xGreen := FALSE;
	RETURN;
END_IF

// State machine
_timer();

IF _timer.Q THEN
	_state := (_state + 1) MOD 4;
	_timer(IN := TRUE, PT := _times[_state]);
END_IF

// Output mapping
CASE _state OF
	0: xRed := TRUE;  xYellow := FALSE; xGreen := FALSE;
	1: xRed := TRUE;  xYellow := TRUE;  xGreen := FALSE;
	2: xRed := FALSE; xYellow := FALSE; xGreen := TRUE;
	3: xRed := FALSE; xYellow := TRUE;  xGreen := FALSE;
END_CASE

eState := _state;

FUNCTION_BLOCK FB_TrafficLight
VAR_INPUT
	xRun : BOOL := FALSE;
	xReset : BOOL := FALSE;
END_VAR
VAR_OUTPUT
	xRed : BOOL := FALSE;
	xYellow : BOOL := FALSE;
	xGreen : BOOL := FALSE;
	eState : USINT := 0; // 0=Red, 1=RedYellow, 2=Green, 3=Yellow
END_VAR
VAR
	_timer : TON;
	_state : USINT := 0;
	_times : ARRAY[0..3] OF TIME := [T#3s, T#1s, T#3s, T#1s];
	_xRunPrev : BOOL := FALSE;
END_VAR

VAR_GLOBAL
	// Test flags for CI/CD
	g_xTestSuiteRunning : BOOL := FALSE;
	g_xAllPassed : BOOL := FALSE;
	g_uiTestCount : UINT := 0;
	g_uiPassCount : UINT := 0;
	g_uiFailCount : UINT := 0;
END_VAR

// 0. Use Method to check if level is within safe range (0 to MAX_CAPACITY)
xLevelOk := ST_METHOD(rValue := rActualLevel,
                      rMin := 0.0,
                      rMax := MAX_CAPACITY,
                      iStatusCode => iLevelStatus);

// 1. Calculate level difference in temporary variable.
rLevelDiff := rLevelSetpoint - rActualLevel;
//Modificataion
// 2. Control logic
IF xEnable AND NOT xInternalError THEN

	IF xAutoMode THEN
		// Start pump based on setpoint with hysteresis
		IF rActualLevel < rLevelSetpoint - 5.0 AND NOT xPumpActive THEN
			fbStartupDelay(IN := TRUE, PT := T#2S);
			IF fbStartupDelay.Q THEN
				xPumpActive := TRUE;
				iStartCounter := iStartCounter + 1; // Update counter
			END_IF
		ELSIF rActualLevel >= rLevelSetpoint THEN
			xPumpActive := FALSE;
			fbStartupDelay(IN := FALSE);
		END_IF
	ELSE
		// In manual mode just monitor limits
		xPumpActive := xEnable AND (rActualLevel < MAX_CAPACITY);
	END_IF

ELSE
	xPumpActive := FALSE;
	fbStartupDelay(IN := FALSE);
END_IF

// 3. Alarm handling
xLowLevelAlarm := (rActualLevel < MIN_LIMIT);

// 4. Operating time accumulation (RETAIN)
IF xPumpActive THEN
	diOperatingSeconds := diOperatingSeconds + 1;
END_IF

// 5. Call Action to calculate flow
ST_ACTION();

// 6. Use Property to work with operating hours
diOperatingHours := ST_PROPERTY; // GET: Read hours converted from seconds

IF xResetHours THEN
    ST_PROPERTY := 0;            // SET: Reset seconds by setting property hours to 0
    xResetHours := FALSE;
END_IF

// 7. Status update
IF xLowLevelAlarm THEN
	diGlobalStatus := 999; // Error code
ELSIF xPumpActive THEN
	diGlobalStatus := 100; // Running
ELSE
	diGlobalStatus := 0;   // Standby
END_IF

// 8. Call example Function Block instance
fbExample(xEnable:= TRUE);
fbExample.ST_FB_Action();
fbExample.ST_FB_Method(iValueToAdd:= 1);

ST_Function(rValue:= 10.0, rMin:= 4.0, rMax:= 20.0);

// 1. Accessing property of another program (ST_PROGRAMM)
// This is a GET access to the property in ST_PROGRAMM
diTotalHours := ST_PROGRAMM.ST_PROPERTY;

// 2. Logic to determine if maintenance is needed
IF diTotalHours >= MAINTENANCE_INTERVAL THEN
	xMaintenanceReq := TRUE;
ELSE
	xMaintenanceReq := FALSE;
END_IF

// 3. Example of direct variable access between programs.
// Reading a standard variable from ST_PROGRAMM
IF ST_PROGRAMM.xLowLevelAlarm AND iLogCounter < 100 THEN
    iLogCounter := iLogCounter + 1;
    // Here we could call a logging function
END_IF

// 4. Example of writing to another program
// We can reset the hours in the main program via its property
IF xMaintenanceReq AND ST_PROGRAMM.xAutoMode = FALSE THEN
    // Potentially reset hours after maintenance in manual mode
    // ST_PROGRAMM.ST_PROPERTY := 0; // SET access
END_IF

iLogCounter.0 := xBIT;

iLogCounter := BIT_TO_INT(xBIT);

IF xEnable THEN
	IF iCounter < _iLimit THEN
		iCounter := iCounter + 1;
		xLimitReached := FALSE;
	ELSE
		xLimitReached := TRUE;
	END_IF
ELSE
	xLimitReached := FALSE;
END_IF

FUNCTION ST_Function : BOOL
VAR_INPUT
	rValue : REAL;
	rMin : REAL;
	rMax : REAL;
END_VAR
VAR
END_VAR

